package com.openclassrooms.mddapi.mapper;

import java.util.List;

import org.mapstruct.Mapper;
import org.mapstruct.Mapping;

import com.openclassrooms.mddapi.dto.CommentResponse;
import com.openclassrooms.mddapi.dto.PostDetailResponse;
import com.openclassrooms.mddapi.dto.PostResponse;
import com.openclassrooms.mddapi.model.Comment;
import com.openclassrooms.mddapi.model.Post;

/**
 * Converts {@link Post} and {@link Comment} entities into API responses.
 * The implementation is generated by MapStruct at compile time.
 */
@Mapper(componentModel = "spring")
public interface PostMapper {

	/**
	 * Builds the API representation of a post, flattening its author and its topic.
	 *
	 * @param post the entity to convert
	 * @return the post response
	 */
	@Mapping(target = "authorUsername", source = "author.username")
	@Mapping(target = "topicId", source = "topic.id")
	@Mapping(target = "topicName", source = "topic.name")
	PostResponse toResponse(Post post);

	/**
	 * Builds the page of an article with its comments.
	 *
	 * @param post     the entity to convert
	 * @param comments the comments of the article, oldest first
	 * @return the post detail response
	 */
	@Mapping(target = "id", source = "post.id")
	@Mapping(target = "createdAt", source = "post.createdAt")
	@Mapping(target = "content", source = "post.content")
	@Mapping(target = "authorUsername", source = "post.author.username")
	@Mapping(target = "topicId", source = "post.topic.id")
	@Mapping(target = "topicName", source = "post.topic.name")
	@Mapping(target = "comments", source = "comments")
	PostDetailResponse toDetail(Post post, List<Comment> comments);

	/**
	 * Builds the API representation of a comment.
	 *
	 * @param comment the entity to convert
	 * @return the comment response
	 */
	@Mapping(target = "authorUsername", source = "author.username")
	CommentResponse toResponse(Comment comment);

}
